import * as react_jsx_runtime from 'react/jsx-runtime';
import { GraphicsObject } from 'graphics-debug';

/**
 * A base class for solvers implementing the standard solve() interface.
 *
 * Solvers should override _step() to implement their logic.
 *
 * Solvers should override visualize() to return a GraphicsObject representing
 * the current state of the solver.
 *
 * Solvers should override getConstructorParams() to return the parameters
 * needed to construct the solver.
 */
declare class BaseSolver {
    MAX_ITERATIONS: number;
    solved: boolean;
    failed: boolean;
    iterations: number;
    progress: number;
    error: string | null;
    activeSubSolver?: BaseSolver | null;
    failedSubSolvers?: BaseSolver[];
    timeToSolve?: number;
    stats: Record<string, any>;
    _setupDone: boolean;
    getSolverName(): string;
    setup(): void;
    /** Override this method to perform setup logic */
    _setup(): void;
    /** DO NOT OVERRIDE! Override _step() instead */
    step(): void;
    /** Override this method to implement solver logic */
    _step(): void;
    getConstructorParams(): void;
    /**
     * Override this method to return the standardized output of the solver.
     * This method should only be called after the solver has completed successfully.
     * Returns null by default - solvers with outputs should override this method.
     */
    getOutput(): any;
    solve(): void;
    visualize(): GraphicsObject;
    /**
     * Called when the solver is about to fail, but we want to see if we have an
     * "acceptable" or "passable" solution. Mostly used for optimizers that
     * have an aggressive early stopping criterion.
     */
    tryFinalAcceptance(): void;
    /**
     * A lightweight version of the visualize method that can be used to stream
     * progress
     */
    preview(): GraphicsObject;
}

interface GenericSolverDebuggerProps {
    solver?: BaseSolver;
    createSolver?: () => BaseSolver;
    animationSpeed?: number;
    onSolverStarted?: (solver: BaseSolver) => void;
    onSolverCompleted?: (solver: BaseSolver) => void;
}
declare const GenericSolverDebugger: ({ solver: solverProp, createSolver, animationSpeed, onSolverStarted, onSolverCompleted, }: GenericSolverDebuggerProps) => react_jsx_runtime.JSX.Element;

type RendererOption = "vector" | "canvas";
interface GenericSolverToolbarProps {
    solver: BaseSolver;
    triggerRender: () => void;
    animationSpeed?: number;
    renderer: RendererOption;
    onRendererChange: (renderer: RendererOption) => void;
    onAnimationSpeedChange: (speed: number) => void;
    onDownloadVisualization: () => void;
    onSolverStarted?: (solver: BaseSolver) => void;
    onSolverCompleted?: (solver: BaseSolver) => void;
}
declare const GenericSolverToolbar: ({ solver, triggerRender, animationSpeed, renderer, onRendererChange, onAnimationSpeedChange, onDownloadVisualization, onSolverStarted, onSolverCompleted, }: GenericSolverToolbarProps) => react_jsx_runtime.JSX.Element;

interface PipelineStep<T extends BaseSolver> {
    solverName: string;
    solverClass: new (...args: any[]) => T;
    getConstructorParams: (pipelineInstance: any) => any[];
    onSolved?: (pipelineInstance: any) => void;
}
declare abstract class BasePipelineSolver<TInput> extends BaseSolver {
    startTimeOfStage: Record<string, number>;
    endTimeOfStage: Record<string, number>;
    timeSpentOnStage: Record<string, number>;
    firstIterationOfStage: Record<string, number>;
    currentPipelineStageIndex: number;
    inputProblem: TInput;
    /** Stores the outputs from each completed pipeline stage */
    pipelineOutputs: Record<string, any>;
    abstract pipelineDef: PipelineStep<any>[];
    constructor(inputProblem: TInput);
    _step(): void;
    solveUntilStage(stageName: string): void;
    getCurrentStageName(): string;
    getStageProgress(): number;
    getStageStats(): Record<string, {
        timeSpent: number;
        iterations: number;
        completed: boolean;
    }>;
    initialVisualize(): GraphicsObject | null;
    finalVisualize(): GraphicsObject | null;
    visualize(): GraphicsObject;
    preview(): GraphicsObject;
    computeProgress(): number;
    /**
     * Get the output from a specific pipeline stage
     */
    getStageOutput<T = any>(stageOutput: string): T | undefined;
    /**
     * Get all pipeline outputs
     */
    getAllOutputs(): Record<string, any>;
    /**
     * Check if a step has completed and produced output
     */
    hasStageOutput(stageName: string): boolean;
    /**
     * Get a solver instance by name
     */
    getSolver<T extends BaseSolver>(stageName: string): T | undefined;
}

interface PipelineStagesTableProps {
    solver: BasePipelineSolver<any>;
    onStepUntilPhase?: (phaseName: string) => void;
    onDownloadInput?: (solver: BaseSolver, stepName: string) => void;
    /** Used for nested tables - removes title and adds indentation */
    isNested?: boolean;
    /** Indentation level for nested tables */
    indentLevel?: number;
    /** Callback to trigger re-render after solver state changes */
    triggerRender?: () => void;
}
declare const PipelineStagesTable: ({ solver, onStepUntilPhase, onDownloadInput, isNested, indentLevel, triggerRender, }: PipelineStagesTableProps) => react_jsx_runtime.JSX.Element;

